// Generated by AI (UnitTest MCP)
//! `GET /api/v1/repositories/:id/constitution` (ADR-0106 decision 3): the
//! active constitution version and clauses governing one repository. Also
//! ADR-0126's Bridge-originated proposal ledger: list, propose, and
//! withdraw a suggested clause change. A proposal is advice, never a gate
//! (ADR-0126 decision 7) -- nothing here writes `constitution_publications`
//! or touches what is active; only a repository's own local
//! `amend_constitution` does that.

use axum::{
    extract::{Path, State},
    http::StatusCode,
    Json,
};
use serde::{Deserialize, Serialize};

use ackplane_server::constitution_store::{
    ActiveConstitution, ClauseSnapshot, ConstitutionProposal, ConstitutionPublication,
    ConstitutionStoreError, ProposeConstitutionClauseRequest,
};

use super::enrolled_or_not_found;
use crate::{unix_seconds, AppState};

#[derive(Serialize)]
pub struct ConstitutionResponse {
    found: bool,
    version_id: Option<String>,
    version: Option<i64>,
    status: Option<String>,
    published_at_seconds: Option<u64>,
    source_reference: Option<String>,
    source_digest_hex: Option<String>,
    clauses: Vec<ConstitutionClauseSummary>,
}

#[derive(Serialize)]
struct ConstitutionClauseSummary {
    id: String,
    slug: String,
    kind: String,
    title: String,
    statement: String,
    status: String,
    consequence: Option<String>,
    scope: Option<String>,
    rationale: Option<String>,
}

impl From<ClauseSnapshot> for ConstitutionClauseSummary {
    fn from(clause: ClauseSnapshot) -> Self {
        Self {
            id: clause.id,
            slug: clause.slug,
            kind: clause.kind,
            title: clause.title,
            statement: clause.statement,
            status: clause.status,
            consequence: clause.consequence,
            scope: clause.scope,
            rationale: clause.rationale,
        }
    }
}

impl ConstitutionResponse {
    fn from_active(
        active: ActiveConstitution,
        publication: Option<ConstitutionPublication>,
    ) -> Self {
        let source_reference = publication
            .as_ref()
            .and_then(|publication| publication.source_reference.clone());
        let source_digest_hex = publication
            .as_ref()
            .and_then(|publication| publication.source_digest.as_deref())
            .map(digest_hex);
        Self {
            found: true,
            version_id: Some(active.version_id),
            version: Some(active.version),
            status: Some(active.status),
            published_at_seconds: unix_seconds(active.published_at),
            source_reference,
            source_digest_hex,
            clauses: active
                .clauses
                .into_iter()
                .map(ConstitutionClauseSummary::from)
                .collect(),
        }
    }

    fn not_found() -> Self {
        Self {
            found: false,
            version_id: None,
            version: None,
            status: None,
            published_at_seconds: None,
            source_reference: None,
            source_digest_hex: None,
            clauses: Vec::new(),
        }
    }
}

fn digest_hex(digest: &[u8]) -> String {
    digest.iter().map(|byte| format!("{byte:02x}")).collect()
}

pub async fn repository_constitution(
    State(state): State<AppState>,
    Path(repository_id): Path<String>,
) -> Result<Json<ConstitutionResponse>, StatusCode> {
    enrolled_or_not_found(&state, &repository_id, "constitution").await?;

    let constitution = state.constitution.lock().await;
    match constitution
        .get_active(&state.tenant_id, &repository_id)
        .await
    {
        Ok(Some(active)) => {
            let publication = match constitution
                .get_publication(&state.tenant_id, &repository_id, &active.version_id)
                .await
            {
                Ok(publication) => publication,
                Err(error) => {
                    tracing::error!(%error, "Bridge repository constitution publication query failed");
                    return Err(StatusCode::INTERNAL_SERVER_ERROR);
                }
            };
            Ok(Json(ConstitutionResponse::from_active(active, publication)))
        }
        Ok(None) => Ok(Json(ConstitutionResponse::not_found())),
        Err(error) => {
            tracing::error!(%error, "Bridge repository constitution query failed");
            Err(StatusCode::INTERNAL_SERVER_ERROR)
        }
    }
}

const CONSTITUTION_PAGE: &str = include_str!("../../../static/constitution.html");

pub async fn constitution_page() -> axum::response::Html<&'static str> {
    axum::response::Html(CONSTITUTION_PAGE)
}

